local PrimaryCurrencyBuyItem = Class("PrimaryCurrencyBuyItem")

---@class PrimaryCurrencyBuyItem.Data
---@field index number
---@field select boolean
---@field product OverseaStoreHomeDojo.Product

function PrimaryCurrencyBuyItem:Awake()
    SetButtonAction(self.BtnSelf, Bind(self, self.OnClick))
end

function PrimaryCurrencyBuyItem:RefreshData(data,clickCallBack)
    ---@type PrimaryCurrencyBuyItem.Data
    self.data = data
    self.clickCallBack = clickCallBack
    if self.controller.gameObject.activeSelf == true then
        self:RefreshUI()
    end
end
    
function PrimaryCurrencyBuyItem:RefreshUI()
    CfUtils.FillImage(self.ImgBg, self:GetBgPath(self.data.index))
    CfUtils.FillText(self.TxtPriceCharge, CfUtils.GetCustomDisplayPrice(self.data.product.windowsPriceId,self.data.product.channelProductId,30))
    CfUtils.FillText(self.TxtNum, self.data.product.num)
    local goodsId = checkNumber(self.data.product.icon) == 0 and self.data.product.goodsId or checkNumber(self.data.product.icon)
    local goodsVo = goodsConfMgr:GetGoodsVoById(goodsId)
    CfUtils.FillImage(self.ImgIcon1, goodsVo.photoPath)

    if checkInt(self.data.product.isFirst) == 1 then
        KTool.SetActive(self.DescNumber, true)
        CfUtils.FillText(self.DescNumber,"+"..self.data.product.firstExtraNum)
        local vo = goodsConfMgr:GetGoodsVoById(self.data.product.extraGoodsId)
        CfUtils.FillImage(self.ImgIcon2, vo.photoPath)
    else
        KTool.SetActive(self.DescNumber, false)
    end
    
    KTool.SetActive(self.ImgSelect, self.data.select)
    KTool.SetActive(self.ImgRecommend, self.data.select)
end

function PrimaryCurrencyBuyItem:GetBgPath(index)
    return string.format(OverseaStoreConstants.ImgPath.PrimaryCurrencyIcon, index)
end

function PrimaryCurrencyBuyItem:SetClickCallBack(func)
    self.clickCallBack = func
end

function PrimaryCurrencyBuyItem:OnClick()
    if self.clickCallBack then
        self.clickCallBack(self.data.index)
    end
end


return PrimaryCurrencyBuyItem